import { Component, inject } from '@angular/core';
import {
  FormBuilder,
  FormControl,
  FormGroup,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import { RouterLink } from '@angular/router';
import {
  IonButton,
  IonCol,
  IonContent,
  IonGrid,
  IonIcon,
  IonInput,
  IonItem,
  IonLabel,
  IonList,
  IonRow,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { arrowForwardOutline } from 'ionicons/icons';
import { getRoutePath, loginRoutePath } from '../app.routes';
import { AuthService } from '../common/auth/auth.service';
import { LogoComponent } from '../common/logo/logo.component';
import { LoadingService } from '../common/loading/loading.service';

@Component({
    selector: 'app-sign-up',
    templateUrl: './sign-up.page.html',
    styleUrls: ['./sign-up.page.scss'],
    imports: [
        IonContent,
        IonList,
        IonItem,
        IonLabel,
        IonInput,
        IonButton,
        IonGrid,
        IonRow,
        IonCol,
        ReactiveFormsModule,
        RouterLink,
        IonIcon,
        LogoComponent,
    ]
})
export class SignUpPage {
  form: FormGroup<SignUpFormControls> = inject(FormBuilder).group({
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(8)]],
  });

  readonly loginRouterLink = [getRoutePath(loginRoutePath)];

  private authService = inject(AuthService);
  private loadingService = inject(LoadingService);

  constructor() {
    addIcons({ arrowForwardOutline });
  }

  async handleSignUp(event: any) {
    event.preventDefault();
    this.loadingService.setLoading(true);

    const credentials = this.form.value as SignUpFormValue;
    await this.authService.signUp(credentials);

    this.loadingService.setLoading(false);
  }
}

type SignUpFormControl = FormControl<string | null>;
type SignUpFormControls = SignUpForm<SignUpFormControl>;
type SignUpFormValue = SignUpForm<string>;

interface SignUpForm<T extends string | FormControl<string | null>> {
  email: T;
  password: T;
}
